                        "StreamArtistContentConsent(address core,address metadataContract,uint256 collectionId,bytes32 familyId,bytes32 newStateHash,uint256 nonce,uint64 deadline)"
                    ),
                    e.core,
                    p.metadataContract,
                    p.collectionId,
                    p.familyId,
                    p.newStateHash,
                    a.nonce,
                    a.time
                )
            )
        );
