pragma solidity ^0.8.19;
import "./StreamArtistAuthorityCheckpoint.sol";
import { StreamArtistPayloadStore } from "./StreamArtistPayloadStore.sol";

import "./StreamArtistIdentityState.sol";
import "./StreamArtistRotationState.sol";
import "../../interfaces/stream/artist/IStreamArtistIdentityRevision.sol";

/// @notice Linked operation-25 mechanics over the sole Identity owner's storage.
library StreamArtistIdentityRevisionState {
    struct State {
        mapping(bytes32 => bytes32) latestRecord;
        mapping(bytes32 => StreamArtistIdentityRevisionTypes.Record) records;
        mapping(bytes32 => bytes32) pendingRecord;
        mapping(bytes32 => R.ProvisionalAssociation) associations;
    }

    event ArtistIdentityRevisionRecorded(
        uint16 schemaVersion,
        bytes32 indexed artistId,
        address indexed signer,
        bytes32 previousRecordHash,
        bytes32 revisedRecordHash,
        string identityRecordURI,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 revisionRecordHash
    );
    event ArtistIdentityDisplayNameStored(
        bytes32 indexed artistId, bytes32 indexed identityRecordHash, string displayName
    );

    function digest(
        StreamArtistHashes.Environment memory e,
        StreamArtistIdentityRevisionTypes.Revision memory p,
        T.Authorization memory a
    ) public pure returns (bytes32) {
        return StreamArtistHashes.typed(
            e,
            keccak256(
                abi.encode(
                    bytes32(0xbfb7a5d3bc248c8eefbe4f8dfc2ea7d75d18c5cb3f2ab0d56000fd87f4b58603),
                    p.artistId,
                    p.previousRecordHash,
                    p.revisedRecordHash,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function operative(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        bytes32 artistId
    ) internal view returns (bytes32) {
        bytes32 registration = identity.identities[artistId].identityRecordHash;
        if (registration == bytes32(0)) revert T.InvalidIdentity(artistId);
        bytes32 latest = _selected(s, rotations, artistId);
        return latest == bytes32(0) ? registration : s.records[latest].revisedRecordHash;
    }

    function operativeRead(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        bytes32 artistId
    ) public view returns (bytes32) {
        return operative(s, identity, rotations, artistId);
    }

    function metadata(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        bytes32 artistId
    ) public view returns (bytes32 documentHash, string memory uri, string memory displayName) {
        documentHash = operative(s, identity, rotations, artistId);
        bytes32 latest = _selected(s, rotations, artistId);
        if (latest == bytes32(0)) {
            T.Identity storage original = identity.identities[artistId];
            return (documentHash, original.identityRecordURI, original.displayName);
        }
        StreamArtistIdentityRevisionTypes.Record storage r = s.records[latest];
        return (documentHash, r.identityRecordURI, r.displayName);
    }

    function revise(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        StreamArtistIdentityRevisionTypes.Revision memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        bytes memory document,
        string memory displayName
    ) public returns (StreamArtistIdentityState.Mutation memory m) {
        Dismissal.Closure memory empty;
        Dismissal.RevisionContinuation memory none;
        return _revise(
            s, identity, rotations, replay, o, c, p, a, proof, document, displayName, empty, none
        );
    }

    function reviseWithResolution(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        StreamArtistIdentityRevisionTypes.Revision memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        bytes memory document,
        string memory displayName,
        Dismissal.Closure memory closure,
        Dismissal.RevisionContinuation memory continuation
    ) public returns (StreamArtistIdentityState.Mutation memory m) {
        return _revise(
            s,
            identity,
            rotations,
            replay,
            o,
            c,
            p,
            a,
            proof,
            document,
            displayName,
            closure,
            continuation
        );
    }

    function _revise(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        StreamArtistIdentityRevisionTypes.Revision memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        bytes memory document,
        string memory displayName,
        Dismissal.Closure memory closure,
        Dismissal.RevisionContinuation memory continuation
    ) private returns (StreamArtistIdentityState.Mutation memory m) {
        if (
            p.previousRecordHash != operative(s, identity, rotations, p.artistId)
                || p.revisedRecordHash == bytes32(0) || p.revisedRecordHash == p.previousRecordHash
                || document.length == 0 || keccak256(document) != p.revisedRecordHash
                || bytes(displayName).length == 0 || a.time == 0 || a.time > block.timestamp
                || (proof.direct && a.time != block.timestamp)
        ) revert T.InvalidRecord();
        if (document.length > 8192) revert T.BoundExceeded(document.length, 8192);
        if (bytes(p.identityRecordURI).length > 2048) {
            revert T.BoundExceeded(bytes(p.identityRecordURI).length, 2048);
        }
        if (bytes(displayName).length > 256) {
            revert T.BoundExceeded(bytes(displayName).length, 256);
        }
        bytes32 pending_ = s.pendingRecord[p.artistId];
        if (
            pending_ != bytes32(0)
                && !StreamArtistRotationState.eligible(
                    rotations, p.artistId, s.associations[pending_]
                )
        ) {
            revert R.ProvisionalChainOccupied(pending_);
        }
        bytes32 previousRevision = _selected(s, rotations, p.artistId);
        bytes32 record = keccak256(
            abi.encode(
                bytes32(0x1b7518e9d16da358d15957ec43218eb0b017fbd017e60c75b3126110006034a4),
                o.environment.chainId,
                o.environment.registry,
                p.artistId,
                p.previousRecordHash,
                p.revisedRecordHash,
                proof.signer,
                identity.identities[p.artistId].authorityClass,
                a.nonce,
                a.time
            )
        );
        if (continuation.continuationHash != bytes32(0) && continuation.artistId != p.artistId) {
            revert T.InvalidRecord();
        }
        bool continuing = continuation.continuationHash != bytes32(0)
            && continuation.stableRevisionRecordHash == previousRevision
            && continuation.stableDocumentHash == p.previousRecordHash;
        bytes32 chainSurface = continuing
            ? keccak256("identity_authority.replay.identity_revision_continuation")
            : keccak256("identity_authority.replay.identity_revision_chain");
        bytes32 chainScope = continuing
            ? keccak256(
                abi.encode(
                    p.artistId,
                    previousRevision,
                    p.previousRecordHash,
                    continuation.continuationHash
                )
            )
            : keccak256(abi.encode(p.artistId, previousRevision, p.previousRecordHash));
        bytes32 chainKey = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                o.environment.chainId,
                o.environment.registry,
                o.coordinator,
                o.archive,
                address(this),
                o.domain,
                chainSurface,
                chainScope
            )
        );
        if (replay[chainKey].status != 0) revert T.Replay(chainKey);
        if (s.records[record].recordHash != bytes32(0)) revert T.InvalidRecord();
        m = StreamArtistIdentityState.authorize(
            identity,
            replay,
            o,
            c,
            p.artistId,
            a,
            proof,
            digest(o.environment, p, a),
            record,
            identity.identities[p.artistId].authorityAddress
        );
        StreamArtistIdentityRevisionTypes.Record memory item =
            StreamArtistIdentityRevisionTypes.Record(
                record,
                p.artistId,
                p.previousRecordHash,
                p.revisedRecordHash,
                previousRevision,
                proof.signer,
                1,
                a.nonce,
                a.time,
                p.identityRecordURI,
                displayName
            );
        s.records[record] = item;
        R.ProvisionalAssociation memory association_ =
            StreamArtistRotationState.associationWithResolution(rotations, p.artistId, closure);
        s.associations[record] = association_;
        if (association_.transitionRecordHash == bytes32(0)) {
            s.latestRecord[p.artistId] = record;
            delete s.pendingRecord[p.artistId];
        } else {
            s.latestRecord[p.artistId] = previousRevision;
            s.pendingRecord[p.artistId] = record;
        }
        if (identity.documents[p.revisedRecordHash].length == 0) {
            identity.documents[p.revisedRecordHash] = document;
            StreamArtistPayloadStore.store(keccak256("ARTIST_IDENTITY_DOCUMENT"), document);
        }
        replay[chainKey] = T.ReplayCell(record, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(chainKey, replay[chainKey]);
        m.record = record;
        m.action = keccak256(abi.encode(p, a, proof, keccak256(document), displayName));
        m.state = keccak256(
            abi.encode(
                m.state,
                previousRevision,
                item,
                association_,
                s.latestRecord[p.artistId],
                s.pendingRecord[p.artistId]
            )
        );
        m.replay = keccak256(abi.encode(m.replay, chainKey, record));
        emit ArtistIdentityRevisionRecorded(
            1,
            p.artistId,
            proof.signer,
            p.previousRecordHash,
            p.revisedRecordHash,
            p.identityRecordURI,
            identity.identities[p.artistId].authorityClass,
            a.nonce,
            a.time,
            record
        );
        emit ArtistIdentityDisplayNameStored(p.artistId, p.revisedRecordHash, displayName);

        if (
            closure.dismissalRecordHash != bytes32(0) || continuation.continuationHash != bytes32(0)
        ) {
            m.state = keccak256(abi.encode(m.state, closure, continuation, continuing));
        }
    }

    function _selected(
        State storage s,
        StreamArtistRotationState.State storage rotations,
        bytes32 artistId
    ) private view returns (bytes32) {
        bytes32 candidate = s.pendingRecord[artistId];
        return candidate != bytes32(0)
            && StreamArtistRotationState.eligible(rotations, artistId, s.associations[candidate])
            ? candidate
            : s.latestRecord[artistId];
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamArtistHashes.sol";
import "./StreamArtistNonceAvailability.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistDelegationTypes as D
} from "../../interfaces/stream/artist/StreamArtistDelegationTypes.sol";

/// @notice Linked implementation operating only on Identity's appended delegation storage.
/// @dev No independent authority or record store. Identity checks Coordinator/snapshot and commits every returned delta.
library StreamArtistDelegationState {
    using StreamArtistNonceAvailability for StreamArtistNonceAvailability.Index;

    struct State {
        mapping(bytes32 => D.Record) records;
        mapping(bytes32 => bytes32) current;
        mapping(bytes32 => StreamArtistNonceAvailability.Index) availability;
        mapping(bytes32 => uint256) hints;
    }

    function grantDigest(StreamArtistHashes.Environment memory e, D.Grant memory p, uint256 nonce)
        public
        pure
        returns (bytes32)
    {
        return StreamArtistHashes.typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistDelegation(address core,address delegate,uint256 collectionId,uint32 capabilities,uint64 notBefore,uint64 expiresAt,uint64 maxUses,bytes32 constraintsHash,uint256 nonce)"
                    ),
                    e.core,
                    p.delegate,
                    p.collectionId,
                    p.capabilities,
                    p.notBefore,
                    p.expiresAt,
                    p.maxUses,
                    p.constraintsHash,
                    nonce
                )
            )
        );
    }

    function revokeDigest(
        StreamArtistHashes.Environment memory e,
        D.Revocation memory p,
        uint256 nonce,
        uint64 deadline
    ) public pure returns (bytes32) {
        return StreamArtistHashes.typed(
            e,
            keccak256(
                abi.encode(
                    keccak256(
                        "StreamArtistDelegationRevocation(bytes32 artistId,address delegate,bytes32 delegationRecordHash,bytes32 reasonHash,uint256 nonce,uint64 deadline)"
                    ),
                    p.artistId,
                    p.delegate,
                    p.delegationRecordHash,
                    p.reasonHash,
                    nonce,
                    deadline
                )
            )
        );
    }

    function grant(
        State storage s,
        StreamArtistHashes.Environment memory e,
        D.Grant memory p,
        address grantor,
        uint256 nonce
    ) public returns (bytes32 record, bytes32 delta) {
        if (
            p.artistId == bytes32(0) || p.delegate == address(0) || p.delegate == grantor
                || p.capabilities == 0 || (p.capabilities & ~uint32(1143)) != 0
                || p.expiresAt <= p.notBefore || block.timestamp >= p.expiresAt
        ) revert T.UnsupportedProfile();
        bytes32 scope = keccak256(abi.encode(p.artistId, p.delegate));
        bytes32 prior = s.current[scope];
        D.Record storage old = s.records[prior];
        // Future grants reserve the key too. A revoked/expired/exhausted grant can be replaced.
        if (
            old.grantor != address(0) && !old.revoked && block.timestamp < old.grant.expiresAt
                && (old.grant.maxUses == 0 || old.uses < old.grant.maxUses)
        ) revert D.ConflictingDelegation(prior);
        record = _grantRecord(e, p, nonce);
        if (s.records[record].grantor != address(0)) revert D.InvalidDelegation(record);
        s.records[record] = D.Record(p, grantor, nonce, 0, false, bytes32(0));
        s.current[scope] = record;
        delta = keccak256(abi.encode(scope, prior, record, s.records[record]));
    }

    function _grantRecord(StreamArtistHashes.Environment memory e, D.Grant memory p, uint256 nonce)
        private
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_DELEGATION_RECORD_V1"),
                e.chainId,
                e.registry,
                p.artistId,
                p.delegate,
                p.collectionId,
                p.capabilities,
                p.notBefore,
                p.expiresAt,
                p.maxUses,
                p.constraintsHash,
                nonce
            )
        );
    }

    function revoke(
        State storage s,
        StreamArtistHashes.Environment memory e,
        D.Revocation memory p,
        address signer,
        uint256 nonce,
        uint64 time
    ) public returns (bytes32 record, bytes32 delta) {
        D.Record storage item = s.records[p.delegationRecordHash];
        if (
            item.grantor == address(0) || item.revoked || item.grantor != signer
                || item.grant.artistId != p.artistId || item.grant.delegate != p.delegate
        ) revert D.InvalidDelegation(p.delegationRecordHash);
        record = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_DELEGATION_REVOCATION_RECORD_V1"),
                e.chainId,
                e.registry,
                p.artistId,
                p.delegate,
                p.delegationRecordHash,
                signer,
                uint8(1),
                p.reasonHash,
                nonce,
                time
            )
        );
        item.revoked = true;
        item.revocationRecordHash = record;
        delta = keccak256(abi.encode(p.delegationRecordHash, item));
    }

    function lane(bytes32 artistId, address delegate) public pure returns (bytes32) {
        return keccak256(
            abi.encode(keccak256("6529STREAM_ARTIST_DELEGATE_NONCE_LANE_V1"), artistId, delegate)
        );
    }

    function active(D.Record memory item) public view returns (bool) {
        return item.grantor != address(0) && !item.revoked
            && block.timestamp >= item.grant.notBefore && block.timestamp < item.grant.expiresAt
            && (item.grant.maxUses == 0 || item.uses < item.grant.maxUses);
    }

    function consume(
        State storage s,
        bytes32 record,
        bytes32 artistId,
        uint256 collectionId,
        uint32 capability,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        address actor,
        bytes32 digest
    ) public returns (bytes32 replayLane, bytes32 delta) {
        D.Record storage item = s.records[record];
        if (!active(item)) revert D.DelegationUnavailable(record);
        if (
            item.grant.artistId != artistId
                || (item.grant.collectionId != 0 && item.grant.collectionId != collectionId)
        ) revert D.DelegationScope(record);
        if ((item.grant.capabilities & capability) == 0) {
            revert D.DelegationCapability(record, capability);
        }
        if (
            proof.signer != item.grant.delegate || proof.digest != digest
                || (proof.direct && (actor != proof.signer || a.signature.length != 0))
                || (!proof.direct && a.signature.length == 0 && proof.signer.code.length == 0)
        ) revert T.InvalidSignature();
        if (a.signature.length > 4096) revert T.BoundExceeded(a.signature.length, 4096);
        replayLane = lane(artistId, proof.signer);
        delta = _consume(s, record, replayLane, a.nonce, proof.direct);
    }

    function _consume(
        State storage s,
        bytes32 record,
        bytes32 replayLane,
        uint256 nonce,
        bool direct
    ) private returns (bytes32 delta) {
        if (direct && nonce != s.hints[replayLane]) revert T.InvalidRecord();
        bytes32 availabilityDelta = s.availability[replayLane].consumeTagged(nonce, 2, replayLane);
        if (nonce == s.hints[replayLane]) {
            (, s.hints[replayLane]) = s.availability[replayLane].firstUnused();
        }
        D.Record storage item = s.records[record];
        ++item.uses;
        delta = keccak256(
            abi.encode(record, item, replayLane, nonce, s.hints[replayLane], availabilityDelta)
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistAuthorityCheckpoint.sol";
import { StreamArtistPayloadStore } from "./StreamArtistPayloadStore.sol";

import "./StreamArtistDelegationState.sol";
import "./StreamArtistAuthorityPolicy.sol";

/// @notice Linked mechanics over Identity's original storage prefix and replay map.
/// @dev Typed owner guards and one semantic commit remain in Identity. This library owns no separate state.
library StreamArtistIdentityState {
    using StreamArtistNonceAvailability for StreamArtistNonceAvailability.Index;

    struct State {
        uint256 nextRegistrationNonce;
        mapping(bytes32 => T.Identity) identities;
        mapping(address => bytes32) activeIdentity;
        mapping(bytes32 => bytes) documents;
        mapping(bytes32 => bytes) signatures;
        mapping(bytes32 => StreamArtistNonceAvailability.Index) nonceAvailability;
    }

    struct OwnerContext {
        StreamArtistHashes.Environment environment;
        address coordinator;
        address archive;
        bytes32 domain;
        uint64 revision;
    }

    struct Mutation {
        bytes32 record;
        bytes32 action;
        bytes32 state;
        bytes32 replay;
    }
    event ArtistDelegationGranted(
        uint16 schemaVersion,
        bytes32 indexed artistId,
        address indexed delegate,
        uint256 indexed collectionId,
        uint32 capabilities,
        uint64 notBefore,
        uint64 expiresAt,
        uint64 maxUses,
        bytes32 constraintsHash,
        uint256 nonce,
        bytes32 delegationRecordHash
    );
    event ArtistDelegationRevoked(
        uint16 schemaVersion,
        bytes32 indexed artistId,
        address indexed delegate,
        bytes32 indexed delegationRecordHash,
        bytes32 reasonHash,
        address signer,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt
    );

    function grantDelegation(
        State storage identity,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistDelegationState.State storage delegations,
        OwnerContext memory o,
        T.ActionContext memory c,
        D.Grant memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof
    ) public returns (Mutation memory m) {
        (bytes32 record, bytes32 delta) = StreamArtistDelegationState.grant(
            delegations, o.environment, p, proof.signer, a.nonce
        );
        bytes32 digest = StreamArtistDelegationState.grantDigest(o.environment, p, a.nonce);
        Mutation memory authorization = authorize(
            identity,
            replay,
            o,
            c,
            p.artistId,
            a,
            proof,
            digest,
            record,
            identity.identities[p.artistId].authorityAddress
        );
        bytes32 key = _consume(
            replay, o, keccak256("identity_authority.replay.delegation_key"), record, record
        );
        m = Mutation(
            record,
            keccak256(abi.encode(p, a, proof)),
            keccak256(abi.encode(delta, identity.identities[p.artistId])),
            keccak256(abi.encode(authorization.replay, key, record))
        );
        emit ArtistDelegationGranted(
            1,
            p.artistId,
            p.delegate,
            p.collectionId,
            p.capabilities,
            p.notBefore,
            p.expiresAt,
            p.maxUses,
            p.constraintsHash,
            a.nonce,
            record
        );
    }

    function revokeDelegation(
        State storage identity,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistDelegationState.State storage delegations,
        OwnerContext memory o,
        T.ActionContext memory c,
        D.Revocation memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof
    ) public returns (Mutation memory m) {
        address grantor = delegations.records[p.delegationRecordHash].grantor;
        (bytes32 record, bytes32 delta) = StreamArtistDelegationState.revoke(
            delegations, o.environment, p, proof.signer, a.nonce, _now()
        );
        bytes32 digest = StreamArtistDelegationState.revokeDigest(o.environment, p, a.nonce, a.time);
        Mutation memory authorization =
            authorize(identity, replay, o, c, p.artistId, a, proof, digest, record, grantor);
        bytes32 key = _consume(
            replay,
            o,
            keccak256("identity_authority.replay.one_way_delegation_revocation"),
            p.delegationRecordHash,
            record
        );
        m = Mutation(
            record,
            keccak256(abi.encode(p, a, proof)),
            keccak256(abi.encode(delta, identity.identities[p.artistId])),
            keccak256(abi.encode(authorization.replay, key, record))
        );
        emit ArtistDelegationRevoked(
            1,
            p.artistId,
            p.delegate,
            p.delegationRecordHash,
            p.reasonHash,
            proof.signer,
            1,
            a.nonce,
            _now()
        );
    }
    event ArtistIdentityRegistered(
        uint16 schemaVersion,
        bytes32 indexed artistId,
        address indexed authorityAddress,
        bytes32 identityRecordHash,
        string identityRecordURI,
        uint256 registrationNonce
    );
    /// @notice Supplementary mirror evidence; the canonical identity document remains authoritative.
    event ArtistIdentityDisplayNameStored(
        bytes32 indexed artistId, bytes32 indexed identityRecordHash, string displayName
    );

    function payoutProof(
        StreamArtistHashes.Environment memory e,
        T.PayoutDesignation memory p,
        address signer,
        T.Authorization memory a
    ) public pure returns (bytes32 record, bytes32 digest) {
        return (
            StreamArtistHashes.payoutRecord(e, p, signer, a.nonce, a.time),
            StreamArtistHashes.payoutDigest(e, p, a)
        );
    }

    function attestationProof(
        StreamArtistHashes.Environment memory e,
        T.Binding memory b,
        T.Attestation memory p,
        address signer,
        T.Authorization memory a
    ) public pure returns (bytes32 record, bytes32 digest) {
        return (
            StreamArtistHashes.attestationRecord(e, p, b.artistId, signer, a.nonce, a.time),
            StreamArtistHashes.attestationDigest(e, p, a)
        );
    }

    function ratificationProof(
        StreamArtistHashes.Environment memory e,
        T.Binding memory b,
        T.Ratification memory p,
        address signer,
        T.Authorization memory a,
        uint64 observed
    ) public pure returns (bytes32 record, bytes32 digest) {
        return (
            StreamArtistHashes.ratificationRecord(e, p, b.artistId, signer, a.nonce, observed),
            StreamArtistHashes.ratificationDigest(e, p, a)
        );
    }

    function register(
        State storage state,
        mapping(bytes32 => T.ReplayCell) storage replay,
        OwnerContext memory o,
        address artist,
        bytes32 documentHash,
        string memory uri,
        bytes memory document,
        string memory displayName
    ) public returns (Mutation memory) {
        if (
            artist == address(0) || documentHash == bytes32(0) || document.length == 0
                || keccak256(document) != documentHash || bytes(displayName).length == 0
        ) revert T.InvalidRecord();
        if (document.length > 8192) revert T.BoundExceeded(document.length, 8192);
        if (bytes(uri).length > 2048) revert T.BoundExceeded(bytes(uri).length, 2048);
        if (bytes(displayName).length > 256) {
            revert T.BoundExceeded(bytes(displayName).length, 256);
        }
        if (state.activeIdentity[artist] != bytes32(0)) revert T.AddressAlreadyRegistered(artist);
        uint256 registrationNonce = state.nextRegistrationNonce++;
        bytes32 artistId =
            StreamArtistHashes.identity(o.environment, artist, documentHash, registrationNonce);
        uint64 now_ = _now();
        state.identities[artistId] =
            T.Identity(artist, 1, 1, now_, now_, documentHash, uri, displayName, 0);
        state.activeIdentity[artist] = artistId;
        if (state.documents[documentHash].length == 0) state.documents[documentHash] = document;
        StreamArtistPayloadStore.store(keccak256("ARTIST_IDENTITY_DOCUMENT"), document);
        // Zero identity namespaces registration allocation; actual artist IDs are nonzero.
        if (artistId == bytes32(0)) revert T.InvalidIdentity(artistId);
        bytes32 key = _consume(
            replay,
            o,
            keccak256("identity_authority.replay.nonce_allocator"),
            keccak256(abi.encode(bytes32(0), registrationNonce)),
            artistId
        );
        Mutation memory mutation = Mutation(
            artistId,
            keccak256(abi.encode(artist, documentHash, uri, displayName, registrationNonce)),
            keccak256(
                abi.encode(artistId, state.identities[artistId], state.nextRegistrationNonce)
            ),
            keccak256(abi.encode(key, artistId))
        );
        emit ArtistIdentityRegistered(1, artistId, artist, documentHash, uri, registrationNonce);
        emit ArtistIdentityDisplayNameStored(artistId, documentHash, displayName);

        return mutation;
    }

    function authorize(
        State storage state,
        mapping(bytes32 => T.ReplayCell) storage replay,
        OwnerContext memory o,
        T.ActionContext memory c,
        bytes32 artistId,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        bytes32 digest,
        bytes32 record,
        address expectedSigner
    ) public returns (Mutation memory) {
        T.Identity storage item = state.identities[artistId];
        StreamArtistAuthorityPolicy.requireOperation(item, artistId, c.operationId);
        return _authorize(state, replay, o, c, artistId, a, proof, digest, record, expectedSigner);
    }

    function authorizeIntentAttestation(
        State storage state,
        mapping(bytes32 => T.ReplayCell) storage replay,
        OwnerContext memory o,
        T.ActionContext memory c,
        bytes32 artistId,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        bytes32 digest,
        bytes32 record,
        address expectedSigner
    ) public returns (Mutation memory) {
        if (c.operationId != 24) revert T.InvalidRecord();
        StreamArtistAuthorityPolicy.requireIntentAttestation(state.identities[artistId], artistId);
        return _authorize(state, replay, o, c, artistId, a, proof, digest, record, expectedSigner);
    }

    function _authorize(
        State storage state,
        mapping(bytes32 => T.ReplayCell) storage replay,
        OwnerContext memory o,
        T.ActionContext memory c,
        bytes32 artistId,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        bytes32 digest,
        bytes32 record,
        address expectedSigner
    ) private returns (Mutation memory) {
        T.Identity storage item = state.identities[artistId];
        if (
            proof.signer != expectedSigner || expectedSigner == address(0) || proof.digest != digest
                || (proof.direct && (c.actor != proof.signer || a.signature.length != 0))
                || (!proof.direct && a.signature.length == 0 && proof.signer.code.length == 0)
        ) revert T.InvalidSignature();
        if (
            proof.direct
                && (a.nonce != item.nonceHint
                    || ((c.operationId == 18 || c.operationId == 24) && a.time != _now()))
        ) revert T.InvalidRecord();
        if (a.signature.length > 4096) revert T.BoundExceeded(a.signature.length, 4096);
        bytes32 digestKey = _key(
            o,
            keccak256("identity_authority.replay.digest_revocation"),
            keccak256(abi.encode(artistId, digest))
        );
        if (replay[digestKey].status != 0) revert T.Replay(digestKey);
        bytes32 observation = _observeDigest(replay, o, artistId, digest);
        bytes32 nonceKey = _consume(
            replay,
            o,
            keccak256("identity_authority.replay.nonce_allocator"),
            keccak256(abi.encode(artistId, a.nonce)),
            digest
        );
        bytes32 availabilityDelta =
            state.nonceAvailability[artistId].consumeTagged(a.nonce, 1, artistId);
        bytes32 attestationKey;
        if (c.operationId == 24) {
            attestationKey = _consume(
                replay,
                o,
                keccak256("identity_authority.replay.attestation_key"),
                keccak256(abi.encode(record)),
                record
            );
        }
        if (proof.signer == item.authorityAddress) item.lastAuthorityActionAt = _now();
        // Relayed nonce validity is independent of the allocator. Updating the hint
        // uses a fixed-depth index, never a scan across earlier signed submissions.
        if (a.nonce == item.nonceHint) {
            (, item.nonceHint) = state.nonceAvailability[artistId].firstUnused();
        }
        state.signatures[record] = a.signature;
        StreamArtistPayloadStore.store(keccak256("ARTIST_SIGNATURE_BUNDLE"), a.signature);
        bytes32 replayDelta = keccak256(
            abi.encode(
                nonceKey,
                digest,
                availabilityDelta,
                attestationKey,
                attestationKey == bytes32(0) ? bytes32(0) : record,
                observation
            )
        );

        return Mutation(
            bytes32(0),
            keccak256(abi.encode(artistId, digest, a, proof, record)),
            keccak256(abi.encode(artistId, item, record, keccak256(a.signature))),
            replayDelta
        );
    }

    function authorizeDelegate(
        State storage state,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistDelegationState.State storage delegations,
        OwnerContext memory o,
        T.ActionContext memory c,
        T.Binding memory b,
        uint256 collectionId,
        uint32 capability,
        bytes32 grant,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        bytes32 digest,
        bytes32 record
    ) public returns (Mutation memory) {
        T.Identity storage item = state.identities[b.artistId];
        if (
            !b.accepted || (b.consentMode != 1 && b.consentMode != 2)
                || ((capability == D.POLICY_CONSENT || capability == D.SALE_CONSENT)
                    && b.consentMode != 2)
                || (item.status != 1
                    && item.status != 2
                    && !((c.operationId == 20
                            || c.operationId == 44
                            || c.operationId == 45
                            || c.operationId == 61)
                        && item.status == 4)) || item.authorityClass != 1
                || item.authorityAddress == address(0)
        ) revert T.InvalidIdentity(b.artistId);
        bytes32 lane = StreamArtistDelegationState.lane(b.artistId, proof.signer);
        bytes32 identityDeny = _key(
            o,
            keccak256("identity_authority.replay.digest_revocation"),
            keccak256(abi.encode(b.artistId, digest))
        );
        if (replay[identityDeny].status != 0) revert T.Replay(identityDeny);
        bytes32 observation = _observeDigest(replay, o, b.artistId, digest);
        bytes32 digestKey = _key(
            o,
            keccak256("identity_authority.replay.delegated_digest_revocation"),
            keccak256(abi.encode(lane, digest))
        );
        if (replay[digestKey].status != 0) revert T.Replay(digestKey);
        bytes32 key = _consume(
            replay,
            o,
            keccak256("identity_authority.replay.delegated_nonce"),
            keccak256(abi.encode(lane, a.nonce)),
            digest
        );
        (, bytes32 delta) = StreamArtistDelegationState.consume(
            delegations, grant, b.artistId, collectionId, capability, a, proof, c.actor, digest
        );
        state.signatures[record] = a.signature;
        StreamArtistPayloadStore.store(keccak256("ARTIST_SIGNATURE_BUNDLE"), a.signature);
        return Mutation(
            bytes32(0),
            keccak256(abi.encode(b, grant, a, proof, record)),
            keccak256(abi.encode(delta, record, keccak256(a.signature))),
            keccak256(abi.encode(key, digest, delta, observation))
        );
    }

    // Observation is distinct from revocation: two existing delegate lanes may
    // execute the same digest, but a previously executed digest cannot be revoked.
    function _observeDigest(
        mapping(bytes32 => T.ReplayCell) storage replay,
        OwnerContext memory o,
        bytes32 artistId,
        bytes32 digest
    ) private returns (bytes32) {
        bytes32 key = _key(
            o,
            keccak256("identity_authority.replay.authorization_consumed_digest"),
            keccak256(abi.encode(artistId, digest))
        );
        if (replay[key].status == 0) {
            replay[key] = T.ReplayCell(digest, o.revision + 1, 1, 2);
            StreamArtistAuthorityCheckpoint.noteReplay(key, replay[key]);
        }
        return keccak256(abi.encode(key, replay[key]));
    }

    function _key(OwnerContext memory o, bytes32 surface, bytes32 scope)
        private
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                o.environment.chainId,
                o.environment.registry,
                o.coordinator,
                o.archive,
                address(this),
                o.domain,
                surface,
                scope
            )
        );
    }

    function _consume(
        mapping(bytes32 => T.ReplayCell) storage replay,
        OwnerContext memory o,
        bytes32 surface,
        bytes32 scope,
        bytes32 commitment
    ) private returns (bytes32 key) {
        key = _key(o, surface, scope);
        if (replay[key].status != 0) revert T.Replay(key);
        replay[key] = T.ReplayCell(commitment, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(key, replay[key]);
    }

    function _now() private view returns (uint64) {
        if (block.timestamp > type(uint64).max) revert T.InvalidRecord();
        return uint64(block.timestamp);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamArtistEconomicOperations.sol";
import "./StreamArtistAttestationOperations.sol";
import "./StreamArtistIdentityRevisionState.sol";
import "./StreamArtistRecordPublicationReads.sol";
import "../../interfaces/stream/artist/IStreamArtistCurrentBindingOwner.sol";

/// @notice Typed identity recipes in the guarded Coordinator's delegatecall context.
library StreamArtistIdentityOperations {
    function revise(
        D.CoordinatorContext memory x,
        address actor,
        StreamArtistIdentityRevisionTypes.Revision memory p,
        T.Authorization memory submitted,
        bytes memory document,
        string memory displayName
    ) public returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x, 25);
        (address signer, uint8 class_, uint8 status,) =
            IStreamArtistIdentityOwner(x.suite.owners[2]).authorityState(p.artistId);
        if (!StreamArtistAuthorityPolicy.ordinary(class_, status, false)) {
            revert T.InvalidIdentity(p.artistId);
        }
        T.Authorization memory effective = _directTime(actor, signer, submitted);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            signer,
            StreamArtistIdentityRevisionState.digest(_environment(x), p, effective),
            effective.signature
        );
        record = IStreamArtistIdentityRevisionOwner(x.suite.owners[2])
            .recordIdentityRevision(
                T.ActionContext(25, actor, before_[2]), p, effective, proof, document, displayName
            );
        _archive(
            x,
            25,
            actor,
            record,
            before_,
            abi.encode(p, submitted, document, displayName, proof, effective)
        );
    }

    function validateProposalIdentity(
        address owner,
        T.BindingProposal memory p,
        bytes memory document,
        string memory displayName
    ) public view {
        IStreamArtistIdentityOwner identity = IStreamArtistIdentityOwner(owner);
        (address authority, uint8 class_, uint8 status,) = identity.authorityState(p.artistId);
        (bytes32 hash, string memory uri, string memory name) =
            IStreamArtistIdentityRevisionOwner(owner).operativeIdentityMetadata(p.artistId);
        if (
            !StreamArtistAuthorityPolicy.ordinary(class_, status, false)
                || authority != p.artistAddress || hash != p.identityRecordHash
                || identity.activeIdentity(p.artistAddress) != p.artistId
                || keccak256(document) != hash
                || keccak256(bytes(displayName)) != keccak256(bytes(name))
                || keccak256(bytes(p.identityRecordURI)) != keccak256(bytes(uri))
        ) {
            revert T.InvalidIdentity(p.artistId);
        }
    }

    function attest(
        D.CoordinatorContext memory x,
        address actor,
        T.Attestation memory p,
        T.Authorization memory submitted,
        bytes memory statement
    ) public returns (bytes32 record) {
        if (p.subjectKind >= 1 && p.subjectKind <= 6) {
            Attest.Subject memory subject;
            return StreamArtistAttestationOperations.attest(
                x, actor, p, subject, false, 0, submitted, statement
            );
        }
        if (p.subjectKind == 7 || p.subjectKind == 8) {
            return _publicationAttestation(x, actor, p, submitted, statement);
        }
        T.Snapshot[7] memory before_ = _snapshots(x, 24);
        T.Binding memory b = StreamArtistOnboardingReads(x.reads).acceptedBinding(p.collectionId);
        if (!IStreamCoreCollectionView(x.suite.core).collectionExists(p.collectionId)) {
            revert T.InvalidAttribution(p.collectionId);
        }
        R.AuthorityFact memory authority =
            StreamArtistCurrentAuthorityFacts.read(x.suite.owners[2], b.artistId, false);
        T.Authorization memory effective = _directTime(actor, authority.authorityAddress, submitted);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            authority.authorityAddress,
            StreamArtistHashes.attestationDigest(_environment(x), p, effective),
            effective.signature
        );
        bytes32 operative;
        if (p.subjectKind == 10) {
            operative = IStreamArtistIdentityRevisionReads(x.suite.owners[2])
                .operativeIdentityRecord(b.artistId);
        }
        record = IStreamArtistIdentityOwner(x.suite.owners[2])
            .consumeAttestation(T.ActionContext(24, actor, before_[2]), b, p, effective, proof);
        bytes32 actual = IStreamArtistCurrentAttributionOwner(x.suite.owners[4])
            .recordAttestationWithAuthority(
                T.ActionContext(24, actor, before_[4]),
                b,
                p,
                operative,
                authority,
                proof.signer,
                effective.nonce,
                effective.time,
                statement
            );
        if (actual != record) revert T.InvalidRecord();
        bytes memory payload = submitted.time == effective.time
            ? abi.encode(b, p, submitted, statement, proof)
            : abi.encode(b, p, submitted, statement, proof, effective);
        if (p.subjectKind == 10) payload = abi.encode(payload, operative);
        payload = abi.encode(payload, authority);
        _archive(x, 24, actor, record, before_, payload);
    }

    function _publicationAttestation(
        D.CoordinatorContext memory x,
        address actor,
        T.Attestation memory p,
        T.Authorization memory submitted,
        bytes memory statement
    ) private returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x, 24);
        T.Binding memory b = StreamArtistRecordPublicationReads.binding(x.suite, p.collectionId);
        (P.Publication memory publication,) =
            StreamArtistRecordPublicationRules.decode(p, statement);
        R.AuthorityFact memory authority =
            StreamArtistCurrentAuthorityFacts.read(x.suite.owners[2], b.artistId, false);
        if (publication.recorder != authority.authorityAddress) revert T.InvalidRecord();
        bytes32 hostCodeHash = StreamArtistRecordPublicationReads.candidate(x.suite, publication);
        T.Authorization memory effective = _directTime(actor, authority.authorityAddress, submitted);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            authority.authorityAddress,
            StreamArtistHashes.attestationDigest(_environment(x), p, effective),
            effective.signature
        );
        record = IStreamArtistIdentityOwner(x.suite.owners[2])
            .consumeAttestation(T.ActionContext(24, actor, before_[2]), b, p, effective, proof);
        bytes32 actual = IStreamArtistRecordPublicationOwner(x.suite.owners[4])
            .recordPublicationAttestation(
                T.ActionContext(24, actor, before_[4]),
                b,
                p,
                authority,
                effective.nonce,
                effective.time,
                statement,
                hostCodeHash
            );
        if (actual != record) revert T.InvalidRecord();
        _archive(
            x,
            24,
            actor,
            record,
            before_,
            abi.encode(
                b, p, submitted, statement, proof, effective, authority, publication, hostCodeHash
            )
        );
    }

    function _directTime(address actor, address signer, T.Authorization memory submitted)
        private
        view
        returns (T.Authorization memory effective)
    {
        effective = T.Authorization(submitted.nonce, submitted.time, submitted.signature);
        if (
            actor == signer && actor != address(0) && submitted.signature.length == 0
                && submitted.time == 0
        ) {
            if (block.timestamp > type(uint64).max) revert T.InvalidRecord();
            effective.time = uint64(block.timestamp);
        }
    }

    function _verify(
        D.CoordinatorContext memory x,
        address actor,
        address signer,
        bytes32 digest,
        bytes memory signature
    ) private view returns (T.SignerApproval memory) {
        if (actor == address(0) || signer == address(0)) {
            revert T.InvalidSignature();
        }
        bool direct = actor == signer && signature.length == 0;
        if (!direct) {
            (uint256 cap,, uint8 failure, uint64 revision) = IStreamGasParameterHost(
                    x.suite.registry
                ).gasParameterInfo(keccak256("6529STREAM_GGP_ARTIST_ERC1271_VERIFY_GAS"));
            if (
                failure != 2 || revision == 0
                    || !StreamArtistRegistryValidatorBase(x.suite.validator)
                        .validateSignerProof(signer, digest, signature, cap)
            ) revert T.InvalidSignature();
        }
        return T.SignerApproval(signer, digest, direct);
    }

    function _environment(D.CoordinatorContext memory x)
        private
        view
        returns (StreamArtistHashes.Environment memory)
    {
        return StreamArtistHashes.Environment(
            block.chainid, x.suite.registry, x.suite.core, x.suite.mintManager
        );
    }

    function _snapshots(D.CoordinatorContext memory x, uint16 op)
        private
        view
        returns (T.Snapshot[7] memory result)
    {
        uint256 mask = op == 25 ? 0x04 : 0x17;
        for (uint256 i; i < 7; ++i) {
            if ((mask & (1 << i)) != 0) {
                result[i] = IStreamArtistOwner(x.suite.owners[i]).ownerStateSnapshotV2();
            }
        }
    }

    function _archive(
        D.CoordinatorContext memory x,
        uint16 op,
        address actor,
        bytes32 record,
        T.Snapshot[7] memory before_,
        bytes memory payload
    ) private {
        bytes32 id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                block.chainid,
                x.suite.registry,
                address(this),
                op,
                actor,
                record
            )
        );
        bytes memory evidence = abi.encode(
            uint16(1), x.configurationHash, op, actor, record, before_, _snapshots(x, op), payload
        );
        (bytes32 hash,, bool appended) =
            IStreamArtistArchiveV2(x.suite.archive).appendArtistEvidenceV2(id, 1, evidence);
        if (!appended || hash != keccak256(evidence)) revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistDisputeAdmission.sol";
import "./StreamArtistAuthorizationState.sol";
import "./StreamArtistCurrentAuthorityFacts.sol";
import "../../interfaces/stream/artist/IStreamArtistCurrentConsentOwner.sol";
import {
    IStreamArtistEconomicsEvidence
} from "../../interfaces/stream/artist/IStreamArtistEconomicsEvidence.sol";

import "./StreamArtistOnboardingReads.sol";
import "./StreamArtistEconomicsHashes.sol";
import "./StreamArtistRegistryValidatorBase.sol";
import "./StreamArtistDelegationState.sol";
import "../../interfaces/stream/artist/IStreamArtistDelegationOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistDelegatedConsentOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistArchiveV2.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import "../../interfaces/stream/core/IStreamCoreCollectionView.sol";

/// @notice Linked typed economic/delegation recipes in the Coordinator's guarded execution context.
/// @dev No semantic state. Facade authentication, immutable code checks and the operation lock stay on Coordinator.
library StreamArtistEconomicOperations {
    function grant(
        D.CoordinatorContext memory x,
        address actor,
        D.Grant memory p,
        T.Authorization memory a
    ) public returns (bytes32 record) {
        StreamArtistDisputeAdmission.requireGrant(x.suite, p);
        T.Snapshot[7] memory before_ = _snapshots(x, 26);
        (address signer, uint8 class_, uint8 status,) =
            IStreamArtistIdentityOwner(x.suite.owners[2]).authorityState(p.artistId);
        if (class_ != 1 || (status != 1 && status != 2)) revert T.InvalidIdentity(p.artistId);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            signer,
            StreamArtistDelegationState.grantDigest(_environment(x), p, a.nonce),
            a.signature
        );
        record = IStreamArtistDelegationOwner(x.suite.owners[2])
            .grantDelegation(T.ActionContext(26, actor, before_[2]), p, a, proof);
        _archive(x, 26, actor, record, before_, abi.encode(p, a, proof));
    }

    function revoke(
        D.CoordinatorContext memory x,
        address actor,
        D.Revocation memory p,
        T.Authorization memory a
    ) public returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x, 27);
        D.Record memory prior = IStreamArtistDelegationOwner(x.suite.owners[2])
            .delegationRecord(p.delegationRecordHash);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            prior.grantor,
            StreamArtistDelegationState.revokeDigest(_environment(x), p, a.nonce, a.time),
            a.signature
        );
        record = IStreamArtistDelegationOwner(x.suite.owners[2])
            .revokeDelegation(T.ActionContext(27, actor, before_[2]), p, a, proof);
        _archive(x, 27, actor, record, before_, abi.encode(prior, p, a, proof));
    }

    function economicsCurrent(
        D.CoordinatorContext memory x,
        address actor,
        T.EconomicsConsent memory p,
        bytes32 delegation,
        T.Authorization memory a
    ) public returns (bytes32) {
        T.Snapshot[7] memory before_ = _snapshots(x, 15);
        StreamArtistOnboardingReads reads = StreamArtistOnboardingReads(x.reads);
        T.Binding memory b = reads.acceptedBinding(p.collectionId);
        _collection(x, p.collectionId);
        T.Payout memory payout = _payout(x, b.artistId);
        bytes memory currentEvidence = reads.requireCurrentEconomics(p, payout.account);
        return _economics(x, actor, b, p, payout, delegation, a, before_, currentEvidence);
    }

    function economicsProspective(
        D.CoordinatorContext memory x,
        address actor,
        T.EconomicsConsent memory p,
        T.FixedEconomicsCandidate memory candidate,
        bytes32 delegation,
        T.Authorization memory a
    ) public returns (bytes32) {
        T.Snapshot[7] memory before_ = _snapshots(x, 15);
        StreamArtistOnboardingReads reads = StreamArtistOnboardingReads(x.reads);
        T.Binding memory b = reads.acceptedBinding(p.collectionId);
        _collection(x, p.collectionId);
        T.Payout memory payout = _payout(x, b.artistId);
        (T.AssignmentFact memory actual, bytes32 previousHash) =
            reads.requireProspectiveEconomicsWithEvidence(p, candidate, payout.account);
        return _economics(
            x,
            actor,
            b,
            p,
            payout,
            delegation,
            a,
            before_,
            abi.encode(candidate, actual, previousHash)
        );
    }

    function economicsProspectiveTemplateFreeze(
        D.CoordinatorContext memory x,
        address actor,
        T.EconomicsConsent memory p,
        T.Authorization memory a
    ) public returns (bytes32) {
        T.Snapshot[7] memory before_ = _snapshots(x, 15);
        StreamArtistOnboardingReads reads = StreamArtistOnboardingReads(x.reads);
        T.Binding memory b = reads.acceptedBinding(p.collectionId);
        _collection(x, p.collectionId);
        T.Payout memory payout = _payout(x, b.artistId);
        bytes memory evidence = reads.requireProspectiveTemplateFreezeEconomics(p, payout.account);
        return _economics(x, actor, b, p, payout, bytes32(0), a, before_, evidence);
    }

    function economicsProspectiveTemplate(
        D.CoordinatorContext memory x,
        address actor,
        T.EconomicsConsent memory p,
        bytes32 templateId,
        T.Authorization memory a
    ) public returns (bytes32) {
        T.Snapshot[7] memory before_ = _snapshots(x, 15);
        StreamArtistOnboardingReads reads = StreamArtistOnboardingReads(x.reads);
        T.Binding memory b = reads.acceptedBinding(p.collectionId);
        _collection(x, p.collectionId);
        T.Payout memory payout = _payout(x, b.artistId);
        bytes memory evidence =
            reads.requireProspectiveTemplateEconomics(p, templateId, payout.account);
        return _economics(x, actor, b, p, payout, bytes32(0), a, before_, evidence);
    }

    function _economics(
        D.CoordinatorContext memory x,
        address actor,
        T.Binding memory b,
        T.EconomicsConsent memory p,
        T.Payout memory payout,
        bytes32 delegation,
        T.Authorization memory a,
        T.Snapshot[7] memory before_,
        bytes memory candidateEvidence
    ) private returns (bytes32 record) {
        D.Record memory prior;
        R.AuthorityFact memory authority =
            StreamArtistCurrentAuthorityFacts.read(x.suite.owners[2], b.artistId, false);
        address signer = authority.authorityAddress;
        if (delegation != bytes32(0)) {
            prior = IStreamArtistDelegationOwner(x.suite.owners[2]).delegationRecord(delegation);
            signer = prior.grant.delegate;
        }
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            signer,
            StreamArtistEconomicsHashes.economicsDigest(_environment(x), p, a.nonce, a.time),
            a.signature
        );
        bytes32 actual;
        if (delegation == bytes32(0)) {
            record = IStreamArtistIdentityOwner(x.suite.owners[2])
                .consumeEconomics(
                    T.ActionContext(15, actor, before_[2]), b, p, payout.recordHash, a, proof
                );
            actual = IStreamArtistCurrentConsentOwner(x.suite.owners[6])
                .recordEconomicsWithAuthority(
                    T.ActionContext(15, actor, before_[6]),
                    b,
                    p,
                    payout,
                    proof.signer,
                    a.nonce,
                    authority
                );
        } else {
            record = IStreamArtistDelegationOwner(x.suite.owners[2])
                .consumeDelegatedEconomics(
                    T.ActionContext(15, actor, before_[2]),
                    b,
                    p,
                    payout.recordHash,
                    delegation,
                    a,
                    proof
                );
            actual = IStreamArtistDelegatedConsentOwner(x.suite.owners[6])
                .recordDelegatedEconomics(
                    T.ActionContext(15, actor, before_[6]),
                    b,
                    p,
                    payout,
                    proof.signer,
                    a.nonce,
                    delegation
                );
        }
        if (actual != record) revert T.InvalidRecord();
        IStreamArtistEconomicsEvidence.Association memory association =
            IStreamArtistEconomicsEvidence(x.suite.owners[6]).economicsRecordAssociation(record);
        bytes memory payload = abi.encode(b, p, payout, a, proof, candidateEvidence, association);
        if (delegation != bytes32(0)) payload = abi.encode(payload, delegation, prior);
        _archive(x, 15, actor, record, before_, payload);
    }

    function freeze(
        D.CoordinatorContext memory x,
        address actor,
        T.RoyaltyFreeze memory p,
        bytes32 delegation,
        T.Authorization memory a
    ) public returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x, 20);
        StreamArtistOnboardingReads reads = StreamArtistOnboardingReads(x.reads);
        T.Binding memory b = reads.defensiveBinding(p.collectionId);
        _collection(x, p.collectionId);
        reads.requireRoyaltyFreezeProposal(p);
        D.Record memory prior;
        R.AuthorityFact memory authority =
            StreamArtistCurrentAuthorityFacts.read(x.suite.owners[2], b.artistId, true);
        address signer = authority.authorityAddress;
        if (delegation != bytes32(0)) {
            prior = IStreamArtistDelegationOwner(x.suite.owners[2]).delegationRecord(delegation);
            signer = prior.grant.delegate;
        }
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            signer,
            StreamArtistEconomicsHashes.royaltyFreezeDigest(_environment(x), p, a.nonce, a.time),
            a.signature
        );
        bytes32 actual;
        if (delegation == bytes32(0)) {
            record = IStreamArtistIdentityOwner(x.suite.owners[2])
                .consumeRoyaltyFreeze(T.ActionContext(20, actor, before_[2]), b, p, a, proof);
            actual = IStreamArtistCurrentConsentOwner(x.suite.owners[6])
                .authorizeRoyaltyFreezeWithAuthority(
                    T.ActionContext(20, actor, before_[6]), b, p, proof.signer, a.nonce, authority
                );
        } else {
            record = IStreamArtistDelegationOwner(x.suite.owners[2])
                .consumeDelegatedRoyaltyFreeze(
                    T.ActionContext(20, actor, before_[2]), b, p, delegation, a, proof
                );
            actual = IStreamArtistDelegatedConsentOwner(x.suite.owners[6])
                .authorizeDelegatedRoyaltyFreeze(
                    T.ActionContext(20, actor, before_[6]), b, p, proof.signer, a.nonce, delegation
                );
        }
        if (actual != record) revert T.InvalidRecord();
        bytes memory payload = abi.encode(b, p, a, proof);
        if (delegation != bytes32(0)) payload = abi.encode(payload, delegation, prior);
        _archive(x, 20, actor, record, before_, payload);
    }

    function _payout(D.CoordinatorContext memory x, bytes32 artistId)
        private
        view
        returns (T.Payout memory payout)
    {
        (payout.account, payout.recordHash) =
            StreamArtistOnboardingReads(x.reads).artistPayoutAccount(artistId);
        if (payout.account == address(0) || payout.recordHash == bytes32(0)) {
            revert T.MissingMintPrerequisite(keccak256("payout"));
        }
    }

    function revokeAuthorization(
        D.CoordinatorContext memory x,
        address actor,
        StreamArtistAuthorizationTypes.Revocation memory p,
        T.Authorization memory a
    ) public returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x, 54);
        (address signer,,,) =
            IStreamArtistIdentityOwner(x.suite.owners[2]).authorityState(p.artistId);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            signer,
            StreamArtistAuthorizationState.digest(_environment(x), p, a),
            a.signature
        );
        record = IStreamArtistAuthorizationOwner(x.suite.owners[2])
            .revokeAuthorization(T.ActionContext(54, actor, before_[2]), p, a, proof);
        _archive(x, 54, actor, record, before_, abi.encode(p, a, proof));
    }

    function _verify(
        D.CoordinatorContext memory x,
        address actor,
        address signer,
        bytes32 digest,
        bytes memory signature
    ) private view returns (T.SignerApproval memory) {
        if (actor == address(0) || signer == address(0)) {
            revert T.InvalidSignature();
        }
        bool direct = actor == signer && signature.length == 0;
        if (!direct) {
            (uint256 cap,, uint8 failureClass, uint64 revision) = IStreamGasParameterHost(
                    x.suite.registry
                ).gasParameterInfo(keccak256("6529STREAM_GGP_ARTIST_ERC1271_VERIFY_GAS"));
            if (
                revision == 0 || failureClass != 2
                    || !StreamArtistRegistryValidatorBase(x.suite.validator)
                        .validateSignerProof(signer, digest, signature, cap)
            ) revert T.InvalidSignature();
        }
        return T.SignerApproval(signer, digest, direct);
    }

    function _collection(D.CoordinatorContext memory x, uint256 collectionId) private view {
        if (!IStreamCoreCollectionView(x.suite.core).collectionExists(collectionId)) {
            revert T.InvalidAttribution(collectionId);
        }
    }

    function _environment(D.CoordinatorContext memory x)
        private
        view
        returns (StreamArtistHashes.Environment memory)
    {
        return StreamArtistHashes.Environment(
            block.chainid, x.suite.registry, x.suite.core, x.suite.mintManager
        );
    }

    function _snapshots(D.CoordinatorContext memory x, uint16 op)
        private
        view
        returns (T.Snapshot[7] memory result)
    {
        uint256 mask = op == 26 || op == 27 || op == 54 ? 4 : op == 15 ? 0x77 : 0x57;
        for (uint256 i; i < 7; ++i) {
            if ((mask & (1 << i)) != 0) {
                result[i] = IStreamArtistOwner(x.suite.owners[i]).ownerStateSnapshotV2();
            }
        }
    }

    function _archive(
        D.CoordinatorContext memory x,
        uint16 op,
        address actor,
        bytes32 record,
        T.Snapshot[7] memory prior,
        bytes memory payload
    ) private {
        T.Snapshot[7] memory after_ = _snapshots(x, op);
        bytes32 id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                block.chainid,
                x.suite.registry,
                address(this),
                op,
                actor,
                record
            )
        );
        bytes memory evidence =
            abi.encode(uint16(1), x.configurationHash, op, actor, record, prior, after_, payload);
        (bytes32 hash,, bool appended) =
            IStreamArtistArchiveV2(x.suite.archive).appendArtistEvidenceV2(id, 1, evidence);
        if (!appended || hash != keccak256(evidence)) revert T.InvalidRecord();
    }
}

