pragma solidity ^0.8.19;
import "./StreamArtistAuthorityCheckpoint.sol";
import "./StreamArtistEconomicsAssociation.sol";
import {
    IStreamArtistEconomicsEvidence as EconomicsEvidence
} from "../../interfaces/stream/artist/IStreamArtistEconomicsEvidence.sol";

import "./StreamArtistEconomicsHashes.sol";
import "./StreamArtistSaleHashes.sol";

/// @notice Linked typed Consent mechanics; the owner retains its guard and single semantic commit.
/// @dev Mapping references are the owner's existing slots. No new owner or external authorization path.
library StreamArtistConsentState {
    struct Context {
        StreamArtistHashes.Environment environment;
        address coordinator;
        address archive;
        bytes32 domain;
        uint64 revision;
        uint64 observedAt;
    }

    struct Mutation {
        bytes32 record;
        bytes32 action;
        bytes32 state;
        bytes32 replay;
    }

    event ArtistSaleConsentRecorded(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed saleConfigHash,
        address indexed signer,
        bytes32 saleId,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 consentRecordHash
    );

    function saleConsent(
        mapping(bytes32 => Sale.Record) storage records,
        mapping(bytes32 => bytes32) storage latest,
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        T.Binding memory b,
        Sale.Consent memory p,
        address signer,
        uint256 nonce
    ) public returns (Mutation memory m) {
        return saleConsentForAuthority(records, latest, replay, o, b, p, signer, 1, nonce);
    }

    function saleConsentForAuthority(
        mapping(bytes32 => Sale.Record) storage records,
        mapping(bytes32 => bytes32) storage latest,
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        T.Binding memory b,
        Sale.Consent memory p,
        address signer,
        uint8 principalClass,
        uint256 nonce
    ) public returns (Mutation memory m) {
        if (
            p.collectionId == 0 || p.saleAdapter == address(0) || p.saleId == bytes32(0)
                || p.saleConfigHash == bytes32(0)
        ) revert T.InvalidRecord();
        m.record = StreamArtistSaleHashes.record(
            o.environment, p, b.artistId, signer, principalClass, nonce, o.observedAt
        );
        bytes32 scope = keccak256(abi.encode(p, b.generation, b.bindingHash));
        bytes32 key = _consume(
            replay, o, keccak256("consent_finality.replay.sale_consent_key"), scope, m.record
        );
        if (records[m.record].recordHash != bytes32(0)) revert T.InvalidRecord();
        Sale.Record memory item = Sale.Record(
            m.record,
            p,
            b.artistId,
            signer,
            principalClass,
            nonce,
            o.observedAt,
            b.generation,
            b.bindingHash
        );
        bytes32 lookup = StreamArtistSaleHashes.lookup(p.collectionId, p.saleId, p.saleConfigHash);
        records[m.record] = item;
        latest[lookup] = m.record;
        m.action = keccak256(abi.encode(b, p, signer, nonce));
        m.state = keccak256(abi.encode(scope, lookup, item));
        m.replay = keccak256(abi.encode(key, m.record));
        emit ArtistSaleConsentRecorded(
            1,
            p.collectionId,
            p.saleConfigHash,
            signer,
            p.saleId,
            principalClass,
            nonce,
            o.observedAt,
            m.record
        );
    }

    event ArtistPolicyConsentRecorded(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed policyHash,
        address indexed signer,
        bytes32 phaseId,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 consentRecordHash
    );
    event ArtistEconomicsConsentRecorded(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed assignmentHash,
        address indexed signer,
        bytes32 revenueClass,
        uint8 scope,
        uint256 scopeId,
        bytes32 payoutDesignationRecordHash,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 consentRecordHash
    );
    event ArtistRecordDelegation(
        uint16 schemaVersion,
        bytes32 indexed recordHash,
        bytes32 indexed delegationRecordHash,
        bytes32 indexed artistId,
        address resolver,
        bytes32 revenueClass,
        uint8 authorityClass
    );
    event ArtistContentRatificationRecorded(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed contentStateHash,
        address indexed signer,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 ratificationRecordHash
    );

    function policy(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        T.Binding memory b,
        T.PolicyConsent memory p,
        address signer,
        uint256 nonce
    ) public returns (Mutation memory m) {
        return policyForAuthority(records, replay, o, b, p, signer, 1, nonce);
    }

    function policyForAuthority(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        T.Binding memory b,
        T.PolicyConsent memory p,
        address signer,
        uint8 principalClass,
        uint256 nonce
    ) public returns (Mutation memory m) {
        if (p.phaseId == bytes32(0) || p.policyHash == bytes32(0)) {
            revert T.InvalidRecord();
        }
        m.record = StreamArtistHashes.policyRecordForAuthority(
            o.environment, p, b.artistId, signer, principalClass, nonce, o.observedAt
        );
        bytes32 scope = keccak256(abi.encode(p.collectionId, p.phaseId, p.policyHash));
        bytes32 key = _consume(
            replay, o, keccak256("consent_finality.replay.policy_consent_key"), scope, m.record
        );
        records[scope] = m.record;
        m.action = keccak256(abi.encode(b, p, signer, nonce));
        m.state = keccak256(abi.encode(scope, m.record));
        m.replay = keccak256(abi.encode(key, m.record));
        emit ArtistPolicyConsentRecorded(
            1,
            p.collectionId,
            p.policyHash,
            signer,
            p.phaseId,
            principalClass,
            nonce,
            o.observedAt,
            m.record
        );
    }

    function economics(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => bytes32) storage delegations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        T.Binding memory b,
        T.EconomicsConsent memory p,
        T.Payout memory designation,
        address signer,
        uint256 nonce,
        bytes32 grant
    ) public returns (Mutation memory m) {
        return economicsForAuthority(
            records, delegations, replay, o, b, p, designation, signer, 1, nonce, grant
        );
    }

    event ArtistEconomicsConsentAssociated(
        uint16 schemaVersion,
        bytes32 indexed recordHash,
        bytes32 indexed artistId,
        bytes32 indexed bindingHash,
        uint64 bindingGeneration,
        bytes32 payloadHash,
        bytes32 originalRecord
    );

    function economicsAssociatedForAuthority(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => bytes32) storage delegations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        mapping(bytes32 => EconomicsEvidence.Association) storage associations,
        mapping(bytes32 => bytes32) storage associatedRecords,
        Context memory o,
        T.Binding memory b,
        T.EconomicsConsent memory p,
        T.Payout memory designation,
        address signer,
        uint8 principalClass,
        uint256 nonce,
        bytes32 grant
    ) public returns (Mutation memory m) {
        if (b.artistId == bytes32(0) || b.generation == 0 || b.bindingHash == bytes32(0)) {
            revert T.InvalidRecord();
        }
        bytes32 payloadHash = keccak256(abi.encode(p));
        bytes32 original = records[payloadHash];
        bool firstAssociation = original == bytes32(0);
        if (!firstAssociation) {
            EconomicsEvidence.Association memory prior = associations[original];
            if (
                prior.originalRecord != original || prior.payloadHash != payloadHash
                    || prior.artistId == bytes32(0) || prior.bindingGeneration == 0
                    || prior.bindingHash == bytes32(0)
            ) revert T.InvalidRecord();
            firstAssociation = prior.artistId == b.artistId
                && prior.bindingGeneration == b.generation && prior.bindingHash == b.bindingHash;
            if (!firstAssociation && b.generation <= prior.bindingGeneration) {
                revert T.InvalidRecord();
            }
        }
        m = _economics(
            records,
            delegations,
            replay,
            o,
            b,
            p,
            designation,
            signer,
            principalClass,
            nonce,
            grant,
            firstAssociation
                ? payloadHash
                : StreamArtistEconomicsAssociation.continuation(original, p, b),
            firstAssociation
        );
        if (original == bytes32(0)) original = m.record;
        EconomicsEvidence.Association memory association = EconomicsEvidence.Association(
            b.artistId, b.generation, b.bindingHash, payloadHash, original
        );
        bytes32 key =
            StreamArtistEconomicsAssociation.key(p, b.artistId, b.generation, b.bindingHash);
        associations[m.record] = association;
        associatedRecords[key] = m.record;
        m.state = keccak256(abi.encode(m.state, key, association));
        emit ArtistEconomicsConsentAssociated(
            1, m.record, b.artistId, b.bindingHash, b.generation, payloadHash, original
        );
    }

    function economicsForAuthority(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => bytes32) storage delegations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        T.Binding memory b,
        T.EconomicsConsent memory p,
        T.Payout memory designation,
        address signer,
        uint8 principalClass,
        uint256 nonce,
        bytes32 grant
    ) public returns (Mutation memory m) {
        return _economics(
            records,
            delegations,
            replay,
            o,
            b,
            p,
            designation,
            signer,
            principalClass,
            nonce,
            grant,
            keccak256(abi.encode(p)),
            true
        );
    }

    function _economics(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => bytes32) storage delegations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        T.Binding memory b,
        T.EconomicsConsent memory p,
        T.Payout memory designation,
        address signer,
        uint8 principalClass,
        uint256 nonce,
        bytes32 grant,
        bytes32 replayScope,
        bool firstRecord
    ) private returns (Mutation memory m) {
        if (
            designation.account == address(0) || designation.recordHash == bytes32(0)
                || p.resolver == address(0) || p.collectionId == 0 || p.revenueClass == bytes32(0)
                || p.scope > 2
                || (p.scope == 0 && (p.scopeId != 0 || p.assignmentHash == bytes32(0)))
                || (p.scope == 1 && p.scopeId != p.collectionId) || (p.scope == 2 && p.scopeId == 0)
        ) {
            revert T.InvalidRecord();
        }
        uint8 authorityClass = grant == bytes32(0) ? principalClass : 2;
        m.record = StreamArtistEconomicsHashes.economicsRecordForAuthority(
            o.environment,
            p,
            designation.recordHash,
            b.artistId,
            signer,
            authorityClass,
            nonce,
            o.observedAt
        );
        bytes32 scope = keccak256(abi.encode(p));
        bytes32 key = _consume(
            replay, o, keccak256("consent_finality.replay.consent_key"), replayScope, m.record
        );
        if (firstRecord) records[scope] = m.record;
        if (grant != bytes32(0)) delegations[m.record] = grant;
        m.action = grant == bytes32(0)
            ? keccak256(abi.encode(b, p, designation, signer, nonce))
            : keccak256(abi.encode(b, p, designation, signer, nonce, grant));
        m.state = grant == bytes32(0)
            ? keccak256(abi.encode(scope, m.record))
            : keccak256(abi.encode(scope, m.record, grant));
        m.replay = keccak256(abi.encode(key, m.record));
        emit ArtistEconomicsConsentRecorded(
            1,
            p.collectionId,
            p.assignmentHash,
            signer,
            p.revenueClass,
            p.scope,
            p.scopeId,
            designation.recordHash,
            authorityClass,
            nonce,
            o.observedAt,
            m.record
        );
        if (grant != bytes32(0)) {
            emit ArtistRecordDelegation(
                1, m.record, grant, b.artistId, p.resolver, p.revenueClass, 2
            );
        }
    }

    function ratification(
        mapping(uint256 => T.RatificationRecord) storage current,
        mapping(bytes32 => T.RatificationRecord) storage records,
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        T.Binding memory b,
        T.Ratification memory p,
        address signer,
        uint256 nonce
    ) public returns (Mutation memory m) {
        return ratificationForAuthority(current, records, replay, o, b, p, signer, 1, nonce);
    }

    function ratificationForAuthority(
        mapping(uint256 => T.RatificationRecord) storage current,
        mapping(
            bytes32 => T.RatificationRecord
        ) storage records,
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        T.Binding memory b,
        T.Ratification memory p,
        address signer,
        uint8 principalClass,
        uint256 nonce
    ) public returns (Mutation memory m) {
        if (p.metadataContract == address(0) || p.contentStateHash == bytes32(0)) {
            revert T.InvalidRecord();
        }
        T.RatificationRecord storage prior = current[p.collectionId];
        if (
            prior.contentStateHash == p.contentStateHash
                && prior.metadataContract == p.metadataContract
        ) {
            revert T.InvalidRecord();
        }
        m.record = StreamArtistHashes.ratificationRecordForAuthority(
            o.environment, p, b.artistId, signer, principalClass, nonce, o.observedAt
        );
        bytes32 key = _consume(
            replay,
            o,
            keccak256("consent_finality.replay.ratification_key"),
            keccak256(abi.encode(p.collectionId, m.record)),
            m.record
        );
        T.RatificationRecord memory item =
            T.RatificationRecord(m.record, p.contentStateHash, p.metadataContract);
        current[p.collectionId] = item;
        records[m.record] = item;
        m.action = keccak256(abi.encode(b, p, signer, nonce));
        m.state = keccak256(abi.encode(p.collectionId, item));
        m.replay = keccak256(abi.encode(key, m.record));
        emit ArtistContentRatificationRecorded(
            1,
            p.collectionId,
            p.contentStateHash,
            signer,
            principalClass,
            nonce,
            o.observedAt,
            m.record
        );
    }

    function _consume(
        mapping(bytes32 => T.ReplayCell) storage replay,
        Context memory o,
        bytes32 surface,
        bytes32 scope,
        bytes32 record
    ) private returns (bytes32 key) {
        key = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                o.environment.chainId,
                o.environment.registry,
                o.coordinator,
                o.archive,
                address(this),
                o.domain,
                surface,
                scope
            )
        );
        if (replay[key].status != 0) revert T.Replay(key);
        replay[key] = T.ReplayCell(record, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(key, replay[key]);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/artist/IStreamArtistDelegatedConsentOwner.sol";
import "./StreamArtistAttributionPolicy.sol";

import "./StreamArtistContentOperations.sol";
import "./StreamArtistSaleHashes.sol";
import "../../interfaces/stream/artist/IStreamArtistSaleOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistSaleFacts.sol";
import "../../interfaces/stream/modules/IStreamModule.sol";
import "../../interfaces/stream/modules/IStreamModuleRegistry.sol";
import "../../vendor/openzeppelin/IERC165.sol";

/// @notice Typed sale consent over registered immutable adapter facts and actual artist owners.
/// @dev Caller-sensitive validation receives the original adapter from the facade explicitly.
library StreamArtistSaleOperations {
    bytes32 private constant _READ_GAS = keccak256("6529STREAM_GGP_ARTIST_SALE_FACTS_READ_GAS");

    function record(
        StreamArtistDelegationTypes.CoordinatorContext memory x,
        address actor,
        Sale.Consent memory p,
        T.Authorization memory a
    ) public returns (bytes32 result) {
        T.Snapshot[7] memory prior = _snapshots(x.suite);
        T.Binding memory b = _binding(x.suite, p.collectionId, true);
        R.AuthorityFact memory authority =
            StreamArtistCurrentAuthorityFacts.read(x.suite.owners[2], b.artistId, false);
        bytes memory facts = _adapter(x.suite, p);
        bytes32 digest = StreamArtistSaleHashes.digest(_environment(x.suite), p, a);
        bool direct = actor == authority.authorityAddress && a.signature.length == 0;
        if (actor == address(0)) revert T.InvalidSignature();
        if (!direct) {
            (uint256 cap,, uint8 failure, uint64 revision) = IStreamGasParameterHost(
                    x.suite.registry
                ).gasParameterInfo(keccak256("6529STREAM_GGP_ARTIST_ERC1271_VERIFY_GAS"));
            if (
                revision == 0 || failure != 2
                    || !StreamArtistRegistryValidatorBase(x.suite.validator)
                        .validateSignerProof(authority.authorityAddress, digest, a.signature, cap)
            ) {
                revert T.InvalidSignature();
            }
        }
        T.SignerApproval memory proof = T.SignerApproval(authority.authorityAddress, digest, direct);
        result = IStreamArtistSaleIdentityOwner(x.suite.owners[2])
            .consumeSaleConsent(T.ActionContext(16, actor, prior[2]), b, p, a, proof);
        bytes32 actual = IStreamArtistSaleConsentOwner(x.suite.owners[6])
            .recordSaleConsent(
                T.ActionContext(16, actor, prior[6]), b, p, proof.signer, a.nonce, authority
            );
        if (actual != result) revert T.InvalidRecord();
        bytes32 id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                block.chainid,
                x.suite.registry,
                address(this),
                uint16(16),
                actor,
                result
            )
        );
        bytes memory evidence = abi.encode(
            uint16(1),
            x.configurationHash,
            uint16(16),
            actor,
            result,
            prior,
            _snapshots(x.suite),
            abi.encode(b, p, a, proof, authority, facts)
        );
        (bytes32 hash,, bool appended) =
            IStreamArtistArchiveV2(x.suite.archive).appendArtistEvidenceV2(id, 1, evidence);
        if (!appended || hash != keccak256(evidence)) revert T.InvalidRecord();
    }

    function delegatedBinding(T.SuiteConfiguration memory suite, uint256 collectionId)
        public
        view
        returns (T.Binding memory b)
    {
        b = _binding(suite, collectionId, true);
        if (b.consentMode != 2) revert T.UnsupportedProfile();
    }

    function saleFacts(T.SuiteConfiguration memory suite, Sale.Consent memory p)
        public
        view
        returns (bytes memory)
    {
        return _adapter(suite, p);
    }

    function scope(T.SuiteConfiguration memory suite, uint256 collectionId)
        public
        view
        returns (uint8)
    {
        return _binding(suite, collectionId, false).saleConsentScope;
    }

    /// @notice Historical/latest evidence only; current applicability is checked by requireConsent.
    function isConsented(
        T.SuiteConfiguration memory suite,
        uint256 collectionId,
        bytes32 saleId,
        bytes32 config
    ) public view returns (bool, bytes32) {
        bytes32 hash = IStreamArtistSaleConsentOwner(suite.owners[6])
            .saleConsentAt(collectionId, saleId, config);
        return (hash != bytes32(0), hash);
    }

    function requireConsent(
        T.SuiteConfiguration memory suite,
        address adapter,
        uint256 collectionId,
        bytes32 saleId,
        bytes32 config
    ) public view {
        T.Binding memory b = _binding(suite, collectionId, false);
        if (b.saleConsentScope == 0) return;
        b = _binding(suite, collectionId, true);
        Sale.Consent memory p = Sale.Consent(collectionId, adapter, saleId, config);
        IStreamArtistSaleConsentOwner owner = IStreamArtistSaleConsentOwner(suite.owners[6]);
        Sale.Record memory item =
            owner.saleConsentRecord(owner.saleConsentAt(collectionId, saleId, config));
        if (
            item.recordHash == bytes32(0) || item.artistId != b.artistId
                || (item.authorityClass != 1
                    && item.authorityClass != 3
                    && !(item.authorityClass == 2
                        && b.consentMode == 2
                        && IStreamArtistDelegatedConsentOwner(suite.owners[6])
                                .recordDelegation(item.recordHash) != 0))
                || item.bindingGeneration != b.generation || item.bindingHash != b.bindingHash
                || keccak256(abi.encode(item.terms)) != keccak256(abi.encode(p))
        ) {
            revert Sale.SaleConsentUnavailable(collectionId, saleId, config);
        }
        _adapter(suite, p);
    }

    /// @notice Exact independent attribution and authority states, never inferred from missing acceptance.
    function attributionStateEncoded(T.SuiteConfiguration memory suite, uint256 collectionId)
        public
        view
        returns (bytes memory)
    {
        (uint8 state, uint64 generation, bytes32 artistId, uint8 status, bytes32 hash) =
            attributionState(suite, collectionId);
        return abi.encode(state, generation, artistId, status, hash);
    }

    function attributionState(T.SuiteConfiguration memory suite, uint256 collectionId)
        public
        view
        returns (
            uint8 state,
            uint64 generation,
            bytes32 artistId,
            uint8 authorityStatus,
            bytes32 bindingHash
        )
    {
        _selected(suite.core, keccak256("ARTIST_REGISTRY"), suite.registry, _cap(suite));
        _chain(suite);
        T.Binding memory b = IStreamArtistBindingOwner(suite.owners[0]).binding(collectionId);
        (state, generation) =
            IStreamArtistAttributionOwner(suite.owners[4]).attributionState(collectionId);
        if (generation != b.generation) revert T.InvalidAttribution(collectionId);
        artistId = b.artistId;
        bindingHash = b.bindingHash;
        if (artistId != bytes32(0)) {
            (,, authorityStatus,) =
                IStreamArtistIdentityOwner(suite.owners[2]).authorityState(artistId);
        }
    }

    function _binding(T.SuiteConfiguration memory suite, uint256 collectionId, bool accepted)
        private
        view
        returns (T.Binding memory b)
    {
        _chain(suite);
        _selected(suite.core, keccak256("ARTIST_REGISTRY"), suite.registry, _cap(suite));
        b = IStreamArtistBindingOwner(suite.owners[0]).binding(collectionId);
        if (collectionId == 0 || b.bindingHash == bytes32(0) || b.saleConsentScope > 1) {
            revert T.InvalidAttribution(collectionId);
        }
        if (!accepted) return b;
        (uint8 state, uint64 generation) =
            IStreamArtistAttributionOwner(suite.owners[4]).attributionState(collectionId);
        (address authority, uint8 class_, uint8 status,) =
            IStreamArtistIdentityOwner(suite.owners[2]).authorityState(b.artistId);
        if (
            !b.accepted || !StreamArtistAttributionPolicy.acceptedOrSanctioned(state)
                || generation != b.generation
                || !StreamArtistAuthorityPolicy.ordinary(class_, status, false)
                || authority == address(0) || (b.consentMode != 1 && b.consentMode != 2)
        ) revert T.InvalidAttribution(collectionId);
        C.BindingTerms memory terms = IStreamArtistCollaboratorBindingOwner(suite.owners[0])
            .bindingTerms(collectionId, generation);
        if (terms.mode != 0 || terms.threshold != 0 || terms.count > 32) {
            revert T.UnsupportedProfile();
        }
        if (
            IStreamArtistCollaboratorRecordsOwner(suite.owners[1]).acceptedCount(b.bindingHash)
                != terms.count
        ) {
            revert T.InvalidAttribution(collectionId);
        }
    }

    function _adapter(T.SuiteConfiguration memory suite, Sale.Consent memory p)
        private
        view
        returns (bytes memory evidence)
    {
        address adapter = p.saleAdapter;
        if (adapter.code.length == 0 || p.saleId == bytes32(0) || p.saleConfigHash == bytes32(0)) {
            revert Sale.InvalidSaleAdapter(adapter);
        }
        uint256 cap = _cap(suite);
        address registry = _selected(suite.core, keccak256("MODULE_REGISTRY"), address(0), cap);
        bytes32 kind = abi.decode(
            _read(
                adapter, abi.encodeWithSelector(IStreamModule.streamModuleType.selector), 32, cap
            ),
            (bytes32)
        );
        bytes4 interfaceId = abi.decode(
            _read(
                adapter,
                abi.encodeWithSelector(IStreamModule.streamModuleInterfaceId.selector),
                32,
                cap
            ),
            (bytes4)
        );
        if (
            kind == bytes32(0) || interfaceId == bytes4(0) || interfaceId == bytes4(0xffffffff)
                || !abi.decode(
                    _read(
                        registry,
                        abi.encodeCall(
                            IStreamModuleRegistry.isModuleEligible, (adapter, kind, interfaceId)
                        ),
                        32,
                        cap
                    ),
                    (bool)
                )
                || !abi.decode(
                    _read(
                        adapter,
                        abi.encodeCall(
                            IERC165.supportsInterface, (type(IStreamArtistSaleFacts).interfaceId)
                        ),
                        32,
                        cap
                    ),
                    (bool)
                )
                || abi.decode(_read(adapter, abi.encodeWithSignature("core()"), 32, cap), (address))
                    != suite.core
        ) {
            revert Sale.InvalidSaleAdapter(adapter);
        }
        (uint256 collectionId, bytes32 config) = abi.decode(
            _read(
                adapter,
                abi.encodeCall(IStreamArtistSaleFacts.saleConsentFacts, (p.saleId)),
                64,
                cap
            ),
            (uint256, bytes32)
        );
        if (collectionId != p.collectionId || config != p.saleConfigHash) {
            revert Sale.InvalidSaleAdapter(adapter);
        }
        return abi.encode(
            registry, registry.codehash, adapter.codehash, kind, interfaceId, collectionId, config
        );
    }

    function _cap(T.SuiteConfiguration memory suite) private view returns (uint256 cap) {
        uint8 failure;
        uint64 revision;
        (cap,, failure, revision) =
            IStreamGasParameterHost(suite.registry).gasParameterInfo(_READ_GAS);
        if (cap == 0 || failure != 2 || revision == 0) revert T.InvalidBinding();
    }

    function _selected(address core, bytes32 kind, address expected, uint256 cap)
        private
        view
        returns (address target)
    {
        bytes memory data = _read(
            core, abi.encodeCall(IStreamCorePointers.getSatellitePointer, (kind)), 320, cap
        );
        bytes32 word;
        bytes32 hash;
        assembly ("memory-safe") {
            word := mload(add(data, 32))
            hash := mload(add(data, 64))
        }
        target = address(uint160(uint256(word)));
        if (
            uint256(word) >> 160 != 0 || target.code.length == 0 || hash != target.codehash
                || (expected != address(0) && expected != target)
        ) revert T.ComponentChanged(target);
    }

    /// @dev Allocate only the expected fixed result; neither return nor revert data is copied unboundedly.
    function _read(address target, bytes memory callData, uint256 length, uint256 cap)
        private
        view
        returns (bytes memory result)
    {
        uint256 available = gasleft();
        // Includes a cold account access, fixed buffer and instructions before STATICCALL.
        if (cap > (type(uint256).max - 10_000) / 64 * 63) {
            revert Sale.SaleFactsParentGas(available, cap);
        }
        uint256 required = cap + cap / 63 + 10_000;
        if (available < required) revert Sale.SaleFactsParentGas(available, required);
        result = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(
                cap,
                target,
                add(callData, 32),
                mload(callData),
                add(result, 32),
                length
            )
            size := returndatasize()
        }
        if (!ok || size != length) revert Sale.SaleFactsReadFailed(target, bytes4(callData));
    }

    function _chain(T.SuiteConfiguration memory suite) private view {
        if (block.chainid != IStreamArtistOwner(suite.owners[2]).deploymentChainId()) {
            revert T.InvalidBinding();
        }
    }

    function _environment(T.SuiteConfiguration memory suite)
        private
        view
        returns (StreamArtistHashes.Environment memory)
    {
        return StreamArtistHashes.Environment(
            block.chainid, suite.registry, suite.core, suite.mintManager
        );
    }

    function _snapshots(T.SuiteConfiguration memory suite)
        private
        view
        returns (T.Snapshot[7] memory result)
    {
        for (uint256 i; i < 7; ++i) {
            if ((0x57 & (1 << i)) != 0) {
                result[i] = IStreamArtistOwner(suite.owners[i]).ownerStateSnapshotV2();
            }
        }
    }
}

